import numpy as npfrom mirrors import MirrorPrismclass NGonPrism(MirrorPrism):    def __init__(self, ):        self._n = 6        self._adjust_init_        super(NGonPrism, self).__init__()    @classmethod    def get_name(cls):        return "n-polygon"    def _mouse_adjust(self, pos, d_pos, d_button, button_state):        if button_state[0] == 1:            if d_pos is not None:                change = d_pos[1]                if change != 0:                    self._aspect *= (1.05 ** np.sign(change))                    self._mask = None    @classmethod    def get_icon_vertices(cls):        top_y = super().ICON_LAYOUT['fig_top_y']        bottom_y = super().ICON_LAYOUT['fig_bottom_y']        text_y = super().ICON_LAYOUT['text_bottom_y']        img_center_y = (top_y + bottom_y) / 2.0        img_center_x = 0.5        radius = (bottom_y - top_y) / 2.0        theta = np.pi / 3.0        points = []        for i in range(6):            points.append((radius * np.cos(theta) + img_center_x,                           radius * np.sin(theta) + img_center_y))            theta += np.pi / 3.0        final_point_b = np.array(points[0]) * 0.6 + np.array(points[5]) * 0.4        points.append(tuple(final_point_b))        return {'points': points,                'text_center_bottom': [0.5, text_y]}